css:
:root{--bg:#F1F2F6;--ink:#0F172A;--blue:#2563EB;--violet:#60A5FA;--grey:#A0A8B8;--line:#DDE1EA}
html,body{background:#F1F2F6} #stage{background-color:#F1F2F6}
.tag{border-radius:8px} .card{border-radius:18px} .item{border-radius:14px} .btn{border-radius:999px} .sticker{border-radius:12px} #tabs div{border-radius:8px} .who{border-radius:6px}
#tabs{gap:8px;left:24px;right:24px}#tabs div{font-size:22px;padding:9px 11px;border-width:3px}
.logo{display:flex;align-items:center;justify-content:center;gap:22px} .logo .ic2{width:120px;height:120px;border-radius:28px;background:#2563EB;display:grid;place-items:center;box-shadow:8px 8px 0 #0F172A} .logo .ic2 svg{width:70px;height:70px;color:#fff;stroke:#fff}
.brand-t{font-weight:900;font-size:92px;line-height:.92;letter-spacing:-2px;text-align:left;color:#0F172A} .brand-t b{color:#2563EB}
.mock{background:#fff;border:4px solid #0F172A;border-radius:16px;box-shadow:8px 8px 0 #2563EB;padding:16px 22px;font-weight:800;font-size:30px;color:#0F172A;display:flex;align-items:center;gap:16px;margin-top:18px}
.mock .dot{width:20px;height:20px;border-radius:50%;flex:none} .mock small{display:block;font-weight:600;font-size:24px;color:#5B6478}
.red{color:#DC2626} .stampk{display:inline-block;border:6px solid #DC2626;color:#DC2626;font-weight:900;font-size:64px;padding:6px 22px;text-transform:uppercase;border-radius:10px;background:rgba(255,255,255,.85)}
.cahier{width:430px;height:300px;background:#FFF8E1;border:5px solid #0F172A;border-radius:12px;box-shadow:10px 10px 0 #0F172A;margin:30px auto 0;padding:26px 30px;font-family:inherit;position:relative}
.cahier .l{height:4px;background:#C9B98A;margin:30px 0}.cahier .h{font-weight:900;font-size:38px;color:#0F172A}
#panel{container-type:size;background:#F1F2F6;border-left:5px solid #0F172A;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4.5cqw;padding:6cqw;color:#0F172A}
#panel .pl{display:flex;align-items:center;gap:3cqw;justify-content:center} #panel .pi{width:16cqw;height:16cqw;border-radius:4cqw;background:#2563EB;display:grid;place-items:center;box-shadow:1.2cqw 1.2cqw 0 #0F172A} #panel .pi svg{width:10cqw;height:10cqw;stroke:#fff;color:#fff}
#panel .pn{font-weight:900;font-size:12cqw;line-height:.9;text-align:left;letter-spacing:-.3cqw} #panel .pn b{color:#2563EB}
#panel .ph{font-weight:900;font-size:8cqw;line-height:1.08;text-transform:uppercase} #panel .ph b{color:#2563EB}
#panel .pc{display:flex;flex-direction:column;gap:1.8cqw;align-items:stretch;width:100%} #panel .pc span{background:#fff;border:.7cqw solid #0F172A;border-radius:2.4cqw;font-weight:800;font-size:4.8cqw;padding:1.8cqw 3cqw;text-align:left}
#panel .pb{background:#2563EB;color:#fff;border-radius:999px;font-weight:900;font-size:6.4cqw;padding:3.4cqw 6cqw;box-shadow:1.2cqw 1.2cqw 0 #0F172A} #panel .pb small{display:block;font-size:4.2cqw;font-weight:700;text-transform:none}
#panel .pm{font-weight:700;font-size:4.4cqw;color:#5B6478} #panel .px{display:none;font-weight:900;font-size:10cqw;line-height:1.05;text-transform:uppercase} #panel .px b{color:#2563EB}
@container (min-aspect-ratio: 1/1){ #panel>*{zoom:.6} #panel{gap:2.4cqh} }
@container (max-width: 400px){ #panel .ph,#panel .pc,#panel .pm{display:none} #panel{gap:7cqw} #panel .pl{flex-direction:column} #panel .pi{width:40cqw;height:40cqw;border-radius:9cqw} #panel .pi span{font-size:22cqw!important} #panel .pn{font-size:18cqw;text-align:center} #panel .pb{font-size:9.5cqw;padding:5cqw 5cqw;border-radius:6cqw} #panel .pb small{font-size:6.6cqw} #panel .px{display:block} }
